  function getFeatureStyle(feature) {
    const isDark = document.body.classList.contains('dark-mode') || document.documentElement.classList.contains('dark');
    const name = feature && feature.properties ? feature.properties.name : '';
    const meta = PROVINCE_METADATA[name] || {};

    let borderColor = isDark ? '#38bdf8' : '#0284c7';
    let fillColor = isDark ? '#0284c7' : '#38bdf8';
    let fillOpacity = 0.06;
    let weight = 1.6;

    if (meta.alertLevel === 'danger') {
      borderColor = '#f43f5e';
      fillColor = '#ef4444';
      fillOpacity = 0.14;
      weight = 2.0;
    } else if (meta.alertLevel === 'warning') {
      borderColor = '#f59e0b';
      fillColor = '#f59e0b';
      fillOpacity = 0.10;
      weight = 1.8;
    }

    return {
      color: borderColor,
      weight: weight,
      opacity: 0.85,
      dashArray: '4, 4',
      fillColor: fillColor,
      fillOpacity: fillOpacity,
      className: 'tactical-province-boundary'
    };
  }

  function highlightFeature(e) {
    const layer = e.target;
    layer.setStyle({
      weight: 2.8,
      color: '#34d399',
      dashArray: '',
      fillColor: '#10b981',
      fillOpacity: 0.22
    });

    if (true) {
      layer.bringToFront();
    }
  }

  function resetHighlight(e) {
    if (geoJsonLayer) {
      geoJsonLayer.resetStyle(e.target);
    }
  }

